const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header required" });
  }

  // Check for cached result
  try {
    const cached = await db.query(
      "SELECT result FROM idempotency_keys WHERE key = $1 AND result IS NOT NULL",
      [idempotencyKey]
    );
    if (cached.length) {
      return res.status(201).json(JSON.parse(cached[0].result));
    }
  } catch (err) {
    // Idempotency table might not exist, continue
  }

  // Create the order
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  // Store idempotency key (best effort)
  try {
    await db.query(
      "INSERT INTO idempotency_keys (key, result) VALUES ($1, $2) ON CONFLICT (key) DO UPDATE SET result = $2",
      [idempotencyKey, JSON.stringify(row)]
    );
  } catch (err) {
    // Ignore—idempotency storage is best-effort
  }

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  res.json(row);
});

module.exports = router;

db.js.text:
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.PGHOST,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

// Callers check out a client and are responsible for releasing it.
async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}

module.exports = { pool, withClient };

