const express = require("express");
const db = require("../db");

const router = express.Router();
const idempotencyKeys = new Map();
const IDEMPOTENCY_TTL = 3600000;

router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key");
  if (!key) return res.status(400).json({ error: "Idempotency-Key header required" });

  const cached = idempotencyKeys.get(key);
  if (cached) {
    if (cached.accountId === req.user.accountId) {
      return res.status(201).json(cached.row);
    }
    return res.status(409).json({ error: "Idempotency key already used by different account" });
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  idempotencyKeys.set(key, { accountId: req.user.accountId, row });
  setTimeout(() => idempotencyKeys.delete(key), IDEMPOTENCY_TTL);

  res.status(201).json(row);
});

