db.js.text:
const { Pool } = require("pg");

const pool = new Pool();

// Every read in the service goes through query(). Every write goes through
// write() — it exists so callers get the RETURNING row back in one shape and
// so there is exactly one place a transaction begins.
async function query(text, params) {
  const res = await pool.query(text, params);
  return res.rows;
}

async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

async function idempotentWrite(idempotencyKey, accountId, text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    const existing = await client.query(
      "SELECT response FROM idempotency_keys WHERE idempotency_key = $1 AND account_id = $2",
      [idempotencyKey, accountId]
    );
    if (existing.rows.length) {
      await client.query("COMMIT");
      return JSON.parse(existing.rows[0].response);
    }

    const res = await client.query(text, params);
    const row = res.rows[0];

    await client.query(
      "INSERT INTO idempotency_keys (idempotency_key, account_id, response) VALUES ($1, $2, $3)",
      [idempotencyKey, accountId, JSON.stringify(row)]
    );

    await client.query("COMMIT");
    return row;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { query, write, idempotentWrite };

